const KEYWORDS_PAKISTAN = [
  'lahore', 'karachi', 'islamabad', 'rawalpindi', 'faisalabad',
  'kurta', 'kurti', 'shalwar kameez', 'lawn suit', 'unstitched lawn',
  'abaya', 'hijab', 'khussa', 'juttay', 'sneakers', 'heels',
  'mobile phone', 'smartphone', 'laptop', 'airpods', 'power bank',
  'fridge', 'washing machine', 'air conditioner', 'solar panel',
  'makeup', 'skincare', 'hair oil', 'perfume',
  'baby diapers', 'baby wipes', 'stroller',
  'gym equipment', 'whey protein', 'cricket bat',
  'car accessories', 'helmet', 'engine oil',
  'rice', 'atta', 'ghee', 'masala', 'dates',
  'vitamins', 'first aid kit', 'thermometer'
];

// Rotate keywords each minute so all keywords eventually run.
const nowMinute = Math.floor(Date.now() / 60000);
const batchSize = 6;
const offset = nowMinute % KEYWORDS_PAKISTAN.length;

const rotated = [...KEYWORDS_PAKISTAN.slice(offset), ...KEYWORDS_PAKISTAN.slice(0, offset)];
const selectedKeywords = [...new Set(rotated.slice(0, batchSize))];

return [{
  json: {
    keywords: selectedKeywords,
    countries: ['PK'],
    minAdsPerPage: 3,
    daysLookback: 14,
    maxPagesPerKeyword: 5,
    adType: 'ALL',
    searchType: 'KEYWORD_UNORDERED',
    apiVersion: 'v25.0',
    spreadsheetId: '1pBYVkOrzarunXq2XhVgUOYOBJuVag3Tk2mjG-WQASTI',
    sheetName: 'CTWA Leads'
  }
}];

const config = $json;
const keywords = Array.isArray(config.keywords) ? config.keywords : [];

return keywords
  .map(k => (k || '').trim())
  .filter(Boolean)
  .map(keyword => ({
    json: {
      ...config,
      keyword,
      countries: Array.isArray(config.countries) && config.countries.length ? config.countries : ['PK']
    }
  }));

const keyword = $json.keyword || $json.keywords || '';
const payload = $json.data || [];

if (!Array.isArray(payload) || payload.length === 0) {
  return [];
}

return payload.map(ad => ({
  json: {
    ...ad,
    keyword
  }
}));

const items = $input.all();
const now = new Date();
const cutoffDate = new Date(now);
cutoffDate.setDate(cutoffDate.getDate() - 14);

const whatsappTerms = [
  'whatsapp', 'wa.me', 'whats app', 'click to whatsapp', 'message on whatsapp',
  'واتس', 'واٹس', 'واٹس ایپ'
];

const whatsappLinkHints = [
  'api.whatsapp.com', 'wa.me/', 'whatsapp.com', 'whatsapp://', 'chat.whatsapp.com'
];

const pageMap = new Map();

function getTextParts(ad) {
  const bodies = Array.isArray(ad.ad_creative_bodies) ? ad.ad_creative_bodies : [];
  const caps = Array.isArray(ad.ad_creative_link_captions) ? ad.ad_creative_link_captions : [];
  return [...bodies, ...caps].filter(Boolean);
}

function normalizeDigits(text) {
  return String(text || '')
    .replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 0x0660))
    .replace(/[۰-۹]/g, d => String(d.charCodeAt(0) - 0x06F0));
}

function extractWhatsappNumbers(text) {
  if (!text) return [];

  const normalized = normalizeDigits(text);
  const matches = normalized.match(/(?:\+92|0092|92|0)?[\s\-()]?3\d{2}[\s\-()]?\d{7}/g) || [];

  const cleaned = matches
    .map(m => m.replace(/[^\d+]/g, ''))
    .map(m => {
      if (m.startsWith('0092')) return `+92${m.slice(4)}`;
      if (m.startsWith('92') && !m.startsWith('+92')) return `+${m}`;
      if (m.startsWith('03')) return `+92${m.slice(1)}`;
      return m;
    })
    .filter(m => /^\+923\d{9}$/.test(m));

  return [...new Set(cleaned)];
}

function hasWhatsappLink(text) {
  const t = String(text || '').toLowerCase();
  return whatsappLinkHints.some(h => t.includes(h));
}

for (const item of items) {
  const ad = item.json;
  if (!ad.page_id) continue;

  const start = ad.ad_delivery_start_time ? new Date(ad.ad_delivery_start_time) : null;
  if (start && start < cutoffDate) continue;

  if (!pageMap.has(ad.page_id)) {
    pageMap.set(ad.page_id, {
      business_name: ad.page_name || 'Unknown',
      page_link: `https://fb.com/${ad.page_id}`,
      active_ads_count: 0,
      qualified_ads_count: 0,
      has_whatsapp: false,
      first_seen: ad.ad_delivery_start_time || '',
      sample_text: '',
      keywords: new Set(),
      whatsapp_numbers: new Set(),
      reasons: new Set()
    });
  }

  const row = pageMap.get(ad.page_id);
  row.active_ads_count += 1;
  if (ad.keyword) row.keywords.add(ad.keyword);

  const textParts = getTextParts(ad);
  const rawText = textParts.join(' ');
  const textLower = rawText.toLowerCase();

  const hasWAIntent = whatsappTerms.some(term => textLower.includes(term));
  const hasWALink = hasWhatsappLink(rawText);
  const numbers = extractWhatsappNumbers(rawText);

  // Stricter qualification: require explicit WA link OR extracted number.
  // Mere mention of "whatsapp" text is not enough to qualify.
  const isQualifiedWhatsapp = hasWALink || numbers.length > 0;

  if (isQualifiedWhatsapp) {
    row.has_whatsapp = true;
    row.qualified_ads_count += 1;
    if (!row.sample_text) row.sample_text = rawText.slice(0, 500);

    if (hasWALink) row.reasons.add('link');
    if (numbers.length) row.reasons.add('number');
    if (hasWAIntent) row.reasons.add('keyword');
  }

  for (const num of numbers) row.whatsapp_numbers.add(num);

  if (ad.ad_delivery_start_time && (!row.first_seen || ad.ad_delivery_start_time < row.first_seen)) {
    row.first_seen = ad.ad_delivery_start_time;
  }
}

const output = [];
for (const row of pageMap.values()) {
  if (row.active_ads_count >= 3 && row.has_whatsapp) {
    output.push({
      business_name: row.business_name,
      page_link: row.page_link,
      ad_creative: row.sample_text || 'whatsapp evidence detected',
      active_ads: row.active_ads_count,
      qualified_ads: row.qualified_ads_count,
      start_date: (row.first_seen || '').slice(0, 10),
      keyword_matched: [...row.keywords].join(', '),
      whatsapp_number: [...row.whatsapp_numbers].join(', '),
      whatsapp_evidence: [...row.reasons].join(', '),
      status: 'new',
      fetched_at: new Date().toISOString()
    });
  }
}

return output.map(json => ({ json }));

const newLeads = $input.all(0).map(i => i.json || {});
const existingRows = $input.all(1).map(i => i.json || {});

const getValueCaseInsensitive = (row, candidates) => {
  const keys = Object.keys(row || {});
  for (const c of candidates) {
    if (row[c] !== undefined && row[c] !== null) return String(row[c]);
    const found = keys.find(k => k.toLowerCase().trim() === c.toLowerCase().trim());
    if (found && row[found] !== undefined && row[found] !== null) return String(row[found]);
  }
  return '';
};

const normalize = v => String(v || '').trim().toLowerCase();
const existingKeys = new Set();

for (const row of existingRows) {
  const page = normalize(getValueCaseInsensitive(row, ['Page Link', 'page_link', 'Page link']));
  const business = normalize(getValueCaseInsensitive(row, ['Business Name', 'business_name', 'Business name']));
  const startDate = normalize(getValueCaseInsensitive(row, ['Start Date', 'start_date']));
  const waNumber = normalize(getValueCaseInsensitive(row, ['WhatsApp Number', 'whatsapp_number']));

  // More permissive than page-only: same page can be re-saved if date/number changes.
  if (page || business) existingKeys.add(`pair::${page}::${business}`);
  if (page || startDate) existingKeys.add(`page_date::${page}::${startDate}`);
  if (page || waNumber) existingKeys.add(`page_wa::${page}::${waNumber}`);
}

const seenInRun = new Set();
const unique = [];

for (const lead of newLeads) {
  const page = normalize(lead.page_link);
  const business = normalize(lead.business_name);
  const startDate = normalize(lead.start_date);
  const waNumber = normalize(lead.whatsapp_number);

  const pairKey = `pair::${page}::${business}`;
  const dateKey = `page_date::${page}::${startDate}`;
  const waKey = `page_wa::${page}::${waNumber}`;

  if (!page && !business) continue;

  const existsAlready = existingKeys.has(dateKey) || (waNumber && existingKeys.has(waKey)) || (!startDate && !waNumber && existingKeys.has(pairKey));
  const seenAlready = seenInRun.has(dateKey) || (waNumber && seenInRun.has(waKey)) || (!startDate && !waNumber && seenInRun.has(pairKey));

  if (existsAlready || seenAlready) continue;

  seenInRun.add(dateKey);
  if (waNumber) seenInRun.add(waKey);
  if (!startDate && !waNumber) seenInRun.add(pairKey);

  unique.push({ json: lead });
}

if (unique.length === 0) {
  return [{ json: { no_new_leads: true, message: 'No unique leads to save', inserted: 0 } }];
}

return unique;

const items = $input.all();

if (!items.length) {
  return [{ json: { timestamp: new Date().toISOString(), inserted: 0, message: 'No data to process' } }];
}

if (items[0].json && items[0].json.no_new_leads) {
  return [{
    json: {
      timestamp: new Date().toISOString(),
      inserted: 0,
      message: items[0].json.message || 'No unique leads to save'
    }
  }];
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    inserted: items.length,
    message: `Saved ${items.length} unique leads`
  }
}];
